def minOperations(nums: list[int], target: int) -> int:
    if sum(nums) < target: return -1
    from collections import Counter
    counts = Counter(nums)
    ops = 0
    i = 0
    while i < 31:
        if (target >> i) & 1:
            if counts[1 << i] > 0:
                counts[1 << i] -= 1
            else:
                j = i
                while j < 31 and counts[1 << j] == 0:
                    j += 1
                counts[1 << j] -= 1
                for k in range(j, i, -1):
                    counts[1 << (k - 1)] += 2
                    ops += 1
                counts[1 << i] -= 1
        counts[1 << (i + 1)] += counts[1 << i] // 2
        i += 1
    return ops

